sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading) {
        return;
    }
    if (newValue == '') {
        var gajax = new GlideAjax('x_hsb11_mss_unst_0.MSS_Unstructured_Instruction_Client_Utils'); // MSSCUSTODY-6109
        gajax.addParam("sysparm_name", "checkAssignTime");
        gajax.addParam("sysparm_taskId", g_form.getUniqueValue().toString());
        gajax.getXML(handleResponse);
    }

    function handleResponse(response) {
        var answer = response.responseXML.documentElement.getAttribute("answer");
        if (answer == 'true') {
            if (typeof g_modal != 'undefined') { //WORKSPACE
                var number = g_form.getValue('number');
                g_modal.alert('Due to inactivity, the current task ' + number + ' is unassigned').then(function() {
                    g_aw.closeRecord();
                });
            }
        }
    }
}


